import re,os,unicodedata
p='research/manuscripts/methods-record/degrader-methods-failure-record.md'
s=open(p,encoding='utf-8').read()
def slug(h):
    h=h.strip().lower()
    h=re.sub(r'[^\w\s\-·⛔⭐⚠]','',h)
    out=''
    for ch in h:
        if ch.isalnum() or ch=='-' : out+=ch
        elif ch.isspace(): out+='-'
    return out
heads={}
for m in re.finditer(r'^#{2,3} (.+)$', s, re.M):
    heads[slug(m.group(1))]=m.group(1)
bad=[]
for m in re.finditer(r'\]\(([^)]+)\)', s):
    t=m.group(1)
    if t.startswith('#'):
        if t[1:] not in heads: bad.append(('ANCHOR',t))
    elif t.startswith('http'): continue
    else:
        f=t.split('#')[0]
        path=os.path.normpath(os.path.join(os.path.dirname(p),f))
        if not os.path.exists(path): bad.append(('PATH',t))
print('headings:', len(heads))
for k in heads: print('  ', k)
print('BAD:', len(bad))
for b in bad: print('  ', b)
PYEOF
echo "EXIT=$?"; grep -E "^BAD|^headings|^  \('" $S/linkcheck.out

